package com.dreamcore.workspace.export;

import com.dreamcore.workspace.identity.*;
import com.dreamcore.workspace.material.ObjectStore;
import java.io.*;
import java.security.*;
import java.time.*;
import java.util.*;
import java.util.function.Consumer;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import tools.jackson.databind.json.JsonMapper;

@Service
public class ExportBatchService {
 public static final long MAX_CONTENT=33554432,MAX_ARCHIVE=41943040;public static final int MAX_ITEMS=50;
 public record Item(int ordinal,ExportSources.Selection selection,UUID versionId,String title,String state,String archivePath,Long sizeBytes,String sha256,String errorCode,boolean visible) {}
 public record Cleanup(String state,String reason,int attempts,Instant completedAt,long removedBytes,String backupState) {}
 public record Batch(UUID id,UUID tenantId,UUID workspaceId,String scope,int revision,String state,int requestedCount,int includedCount,int failedCount,long bytes,String sha256,Instant createdAt,Instant generatedAt,Instant expiresAt,int retentionDays,String errorCode,boolean canDownload,Cleanup cleanup,List<Item> items) {}
 public record Summary(UUID id,UUID tenantId,UUID workspaceId,String scope,int revision,String state,int requestedCount,Instant createdAt,Instant expiresAt,String cleanupState) {}
 public record Page(List<Summary> items,boolean hasMore,List<Integer> retentionDays,int maxItems,long maxBytes) {}
 public record Job(UUID id,UUID tenant,UUID actor,UUID workspace,String scope,int retentionDays,UUID token,List<ExportSources.Selection> selections) {}
 public record Stamp(Instant generatedAt,Instant expiresAt) {}
 public record DownloadInfo(String filename,long bytes,String sha256) {}
 private final JdbcTemplate db;private final IdentityService identities;private final IdentityAudit audit;private final ExportSources sources;private final int maxDays;private final com.dreamcore.workspace.retention.RetentionService retention;private final JsonMapper json=new JsonMapper();
 private final com.dreamcore.workspace.departure.DepartureAccess departure;
    public ExportBatchService(JdbcTemplate db,IdentityService identities,IdentityAudit audit,ExportSources sources,@Value("${dreamcore.exports.max-retention-days:7}") int maxDays,com.dreamcore.workspace.retention.RetentionService retention,com.dreamcore.workspace.departure.DepartureAccess departure){this.departure=departure;this.retention=retention;this.db=db;this.identities=identities;this.audit=audit;this.sources=sources;if(maxDays<1||maxDays>7)throw new IllegalArgumentException("Export retention must be 1..7 days");this.maxDays=maxDays;}
 public List<Integer> retentionDays(){return List.of(1,3,7).stream().filter(n->n<=maxDays).toList();}
 private List<Integer> retentionDays(UUID tenant){int days=retention.policyAt(tenant,"EXPORT_PACKAGE",now()).configuredDays();return retentionDays().stream().filter(n->n<=days).toList();}
 private Instant time(Map<String,Object> r,String k){return r.get(k)==null?null:((java.sql.Timestamp)r.get(k)).toInstant();}
 private Instant now(){return db.queryForObject("SELECT clock_timestamp()",(r,n)->r.getTimestamp(1).toInstant());}
 private Map<String,Object> row(UUID actor,UUID tenant,UUID id,boolean lock){identities.member(actor,tenant,false);var rows=db.queryForList("SELECT * FROM export_batches WHERE tenant_id=? AND owner_id=? AND id=?"+(lock?" FOR UPDATE":""),tenant,actor,id);if(rows.isEmpty())throw new IdentityException(404,"EXPORT_BATCH_NOT_FOUND");departure.requireContentRead(actor,tenant,(UUID)rows.getFirst().get("workspace_id"));return rows.getFirst();}
 private ExportSources.Selection selection(Map<String,Object> r){return new ExportSources.Selection((UUID)r.get("object_id"),(Integer)r.get("version"),(String)r.get("format"));}
 private List<Map<String,Object>> rawItems(UUID id){return db.queryForList("SELECT * FROM export_batch_items WHERE batch_id=? ORDER BY ordinal",id);}
 private boolean usable(Map<String,Object> r){return Set.of("READY","PARTIAL").contains(r.get("state"))&&time(r,"expires_at")!=null&&now().isBefore(time(r,"expires_at"))&&"NONE".equals(r.get("cleanup_state"));}
 private List<UUID> dependencies(UUID id,int ordinal){return db.queryForList("SELECT version_id FROM export_item_sources WHERE batch_id=? AND ordinal=?",UUID.class,id,ordinal);}
 @Transactional public ExportSources.Options options(UUID actor,UUID tenant,UUID workspace,String scope,UUID object,String format,int offset,int limit){
  boolean allowed=sources.scope(actor,tenant,workspace,scope,false);var selections=sources.selectionPage(actor,tenant,workspace,scope,object,format,offset,limit);var visible=new ArrayList<ExportSources.Choice>();for(var s:selections.stream().limit(limit).toList())try{visible.add(sources.inspect(actor,tenant,workspace,scope,s,false));}catch(IdentityException e){if(e.status>=500)throw e;}
  return new ExportSources.Options(visible,selections.size()>limit,allowed,retentionDays(tenant),MAX_ITEMS,MAX_CONTENT);
 }
 @Transactional public Batch create(UUID actor,UUID tenant,UUID workspace,String scope,UUID key,int days,List<ExportSources.Selection> selections){
  sources.validScope(scope);if(workspace==null||!retentionDays().contains(days)||selections==null||selections.isEmpty()||selections.size()>MAX_ITEMS)throw IdentityException.invalid();selections.forEach(sources::valid);if(new HashSet<>(selections).size()!=selections.size())throw IdentityException.invalid();
  String fingerprint=IdentityService.hash(json.writeValueAsString(new Object[]{tenant,workspace,scope,days,selections}));UUID prior=identities.priorRequest(actor,key,"EXPORT_BATCH_CREATE",fingerprint);sources.scope(actor,tenant,workspace,scope,true);if(prior!=null)return get(actor,tenant,prior);
  var policy=retention.policyAt(tenant,"EXPORT_PACKAGE",now());if(days>policy.configuredDays())throw new IdentityException(409,"EXPORT_RETENTION_CHANGED");
  UUID id=UUID.randomUUID();db.update("INSERT INTO export_batches(id,tenant_id,owner_id,workspace_id,scope,retention_days,requested_count,retention_policy_revision) VALUES (?,?,?,?,?,?,?,?)",id,tenant,actor,workspace,scope,days,selections.size(),policy.revision());int i=0;for(var s:selections)db.update("INSERT INTO export_batch_items(batch_id,ordinal,object_id,version,format) VALUES (?,?,?,?,?)",id,++i,s.objectId(),s.version(),s.format());identities.remember(actor,key,"EXPORT_BATCH_CREATE",fingerprint,id);audit.record(actor,tenant,"EXPORT_BATCH_CREATE",id,"SUCCESS");return get(actor,tenant,id);
 }
 @Transactional public Page list(UUID actor,UUID tenant,int offset,int limit,UUID workspace){if(offset<0||offset>100000||limit<1||limit>30)throw IdentityException.invalid();identities.member(actor,tenant,false);var values=db.query("SELECT * FROM export_batches WHERE tenant_id=? AND owner_id=? AND departure_content_readable(owner_id,tenant_id,workspace_id) AND (?::uuid IS NULL OR workspace_id=?) ORDER BY created_at DESC,id LIMIT ? OFFSET ?",(r,n)->new Summary(r.getObject("id",UUID.class),tenant,r.getObject("workspace_id",UUID.class),r.getString("scope"),r.getInt("revision"),r.getString("state"),r.getInt("requested_count"),r.getTimestamp("created_at").toInstant(),r.getTimestamp("expires_at")==null?null:r.getTimestamp("expires_at").toInstant(),r.getString("cleanup_state")),tenant,actor,workspace,workspace,limit+1,offset);return new Page(values.stream().limit(limit).toList(),values.size()>limit,retentionDays(tenant),MAX_ITEMS,MAX_CONTENT);}
 @Transactional public Batch get(UUID actor,UUID tenant,UUID id){
  var r=row(actor,tenant,id,false);UUID workspace=(UUID)r.get("workspace_id");String scope=(String)r.get("scope");var projected=new ArrayList<Item>();boolean readable=true;int included=0,failed=0;
  for(var item:rawItems(id)){String state=(String)item.get("state");if(state.equals("INCLUDED"))included++;if(state.equals("FAILED"))failed++;ExportSources.Choice c=null;try{c=sources.inspect(actor,tenant,workspace,scope,selection(item),true);sources.verifySources(actor,tenant,dependencies(id,(Integer)item.get("ordinal")));}catch(IdentityException e){if(e.status>=500)throw e;c=null;if(state.equals("INCLUDED"))readable=false;}
   boolean visible=c!=null;projected.add(new Item((Integer)item.get("ordinal"),selection(item),visible?c.versionId():null,visible?c.title():null,state,visible?(String)item.get("archive_path"):null,visible?(Long)item.get("bytes"):null,visible?(String)item.get("sha256"):null,visible?(String)item.get("error_code"):"EXPORT_ITEM_UNAVAILABLE",visible));
  }
  var cleanup=new Cleanup((String)r.get("cleanup_state"),(String)r.get("cleanup_reason"),(Integer)r.get("cleanup_attempts"),time(r,"cleaned_at"),(Long)r.get("removed_bytes"),"BACKUPS_SEPARATE");return new Batch(id,tenant,workspace,scope,(Integer)r.get("revision"),(String)r.get("state"),(Integer)r.get("requested_count"),included,failed,(Long)r.get("bytes"),(String)r.get("sha256"),time(r,"created_at"),time(r,"generated_at"),time(r,"expires_at"),(Integer)r.get("retention_days"),(String)r.get("error_code"),usable(r)&&readable&&included>0,cleanup,projected);
 }
 @Transactional public Batch command(UUID actor,UUID tenant,UUID id,UUID key,int expected,String action){
  if(expected<1||!Set.of("RETRY","REMOVE").contains(action))throw IdentityException.invalid();String hash=IdentityService.hash(json.writeValueAsString(new Object[]{tenant,id,expected,action}));UUID prior=identities.priorRequest(actor,key,"EXPORT_BATCH_COMMAND",hash);var r=row(actor,tenant,id,true);if(prior!=null)return get(actor,tenant,id);if((Integer)r.get("revision")!=expected)throw new IdentityException(409,"EXPORT_REVISION_CONFLICT");
  if(action.equals("RETRY")){sources.scope(actor,tenant,(UUID)r.get("workspace_id"),(String)r.get("scope"),true);if(!"FAILED".equals(r.get("state"))||time(r,"expires_at")!=null)throw new IdentityException(409,"EXPORT_STATE_CONFLICT");db.update("UPDATE export_batches SET state='QUEUED',revision=revision+1,error_code=NULL,cleanup_state='NONE',cleanup_reason=NULL,cleaned_at=NULL WHERE id=?",id);}
  else{db.update("UPDATE export_batches SET state='REMOVED',revision=revision+1,lease_token=NULL,lease_until=NULL,cleanup_state=CASE WHEN cleanup_state='COMPLETE' THEN 'COMPLETE' ELSE 'PENDING' END,cleanup_reason='USER_REMOVED' WHERE id=?",id);}
  identities.remember(actor,key,"EXPORT_BATCH_COMMAND",hash,id);audit.record(actor,tenant,"EXPORT_BATCH_"+action,id,"SUCCESS");return get(actor,tenant,id);
 }
 @Transactional public Job claim(){
  var candidates=db.queryForList("SELECT id,tenant_id FROM export_batches WHERE cleanup_state='NONE' AND (state='QUEUED' OR (state='GENERATING' AND lease_until<now())) ORDER BY created_at,id LIMIT 1");if(candidates.isEmpty())return null;db.queryForList("SELECT id FROM tenants WHERE id=? FOR SHARE",candidates.getFirst().get("tenant_id"));var rows=db.queryForList("SELECT * FROM export_batches WHERE id=? AND cleanup_state='NONE' AND (state='QUEUED' OR (state='GENERATING' AND lease_until<now())) FOR UPDATE SKIP LOCKED",candidates.getFirst().get("id"));if(rows.isEmpty())return null;var r=rows.getFirst();UUID id=(UUID)r.get("id"),token=UUID.randomUUID();try{departure.requireContentRead((UUID)r.get("owner_id"),(UUID)r.get("tenant_id"),(UUID)r.get("workspace_id"));}catch(IdentityException stopped){db.update("UPDATE export_batches SET state='REMOVED',revision=revision+1,lease_token=NULL,lease_until=NULL,cleanup_state='PENDING',cleanup_reason='DEPARTURE' WHERE id=?",id);return null;}db.update("DELETE FROM export_archive_chunks WHERE batch_id=?",id);db.update("DELETE FROM export_item_sources WHERE batch_id=?",id);db.update("UPDATE export_batch_items SET state='PENDING',title=NULL,version_id=NULL,archive_path=NULL,bytes=NULL,sha256=NULL,error_code=NULL WHERE batch_id=?",id);db.update("UPDATE export_batches SET state='GENERATING',revision=revision+1,generation=?,lease_token=?,lease_until=now()+interval '10 minutes',attempts=attempts+1,bytes=0,sha256=NULL,error_code=NULL WHERE id=?",token,token,id);
  return new Job(id,(UUID)r.get("tenant_id"),(UUID)r.get("owner_id"),(UUID)r.get("workspace_id"),(String)r.get("scope"),(Integer)r.get("retention_days"),token,rawItems(id).stream().map(this::selection).toList());
 }
 private void owned(Job job){identities.member(job.actor(),job.tenant(),false);departure.requireContentRead(job.actor(),job.tenant(),job.workspace());if(db.queryForList("SELECT id FROM export_batches WHERE id=? AND state='GENERATING' AND lease_token=? AND lease_until>now() FOR UPDATE",job.id(),job.token()).isEmpty())throw new IdentityException(409,"EXPORT_LEASE_LOST");}
 @Transactional public void reserve(Job job,int ordinal,ExportSources.File file,String path){owned(job);for(UUID source:file.sourceVersions())db.update("INSERT INTO export_item_sources(batch_id,ordinal,version_id) VALUES (?,?,?) ON CONFLICT DO NOTHING",job.id(),ordinal,source);db.update("UPDATE export_batch_items SET state='WRITING',title=?,version_id=?,archive_path=?,bytes=?,sha256=? WHERE batch_id=? AND ordinal=?",file.choice().title(),file.choice().versionId(),path,file.bytes().length,ObjectStore.sha256(file.bytes()),job.id(),ordinal);}
 @Transactional public void itemResult(Job job,int ordinal,String error){owned(job);db.update("UPDATE export_batch_items SET state=?,error_code=? WHERE batch_id=? AND ordinal=?",error==null?"INCLUDED":"FAILED",error,job.id(),ordinal);}
 @Transactional public void chunk(Job job,int ordinal,byte[] content){owned(job);if(content.length<1||content.length>65536||ordinal>=640)throw new IdentityException(413,"EXPORT_ARCHIVE_LIMIT");db.update("INSERT INTO export_archive_chunks(batch_id,generation,ordinal,content) VALUES (?,?,?,?)",job.id(),job.token(),ordinal,content);}
 @Transactional public Stamp stamp(Job job){owned(job);var row=db.queryForMap("SELECT * FROM export_batches WHERE id=?",job.id());Instant anchor=time(row,"retention_anchor"),deadline=time(row,"retention_deadline");if(anchor==null){anchor=now();deadline=departure.capPackageExpiry(job.actor(),job.tenant(),job.workspace(),anchor.plus(Duration.ofDays(job.retentionDays())));db.update("UPDATE export_batches SET retention_anchor=?,retention_deadline=? WHERE id=?",java.sql.Timestamp.from(anchor),java.sql.Timestamp.from(deadline),job.id());}Instant capped=departure.capPackageExpiry(job.actor(),job.tenant(),job.workspace(),deadline);if(capped.isBefore(deadline)){deadline=capped;db.update("UPDATE export_batches SET retention_deadline=? WHERE id=?",java.sql.Timestamp.from(deadline),job.id());}if(!now().isBefore(deadline))throw new IdentityException(410,"EXPORT_RETENTION_EXPIRED");return new Stamp(anchor,deadline);}
 @Transactional public List<Item> manifestItems(Job job){owned(job);return rawItems(job.id()).stream().map(r->new Item((Integer)r.get("ordinal"),selection(r),(UUID)r.get("version_id"),(String)r.get("title"),(String)r.get("state"),(String)r.get("archive_path"),(Long)r.get("bytes"),(String)r.get("sha256"),(String)r.get("error_code"),"INCLUDED".equals(r.get("state")))).toList();}
 @Transactional public void finish(Job job,Stamp stamp,long bytes,String sha){
  sources.scope(job.actor(),job.tenant(),job.workspace(),job.scope(),true);owned(job);int included=0,failed=0;for(var i:rawItems(job.id())){if("INCLUDED".equals(i.get("state"))){included++;sources.inspect(job.actor(),job.tenant(),job.workspace(),job.scope(),selection(i),true);sources.verifySources(job.actor(),job.tenant(),dependencies(job.id(),(Integer)i.get("ordinal")));}else failed++;}
  if(included==0||bytes<1||bytes>MAX_ARCHIVE)throw new IdentityException(409,"EXPORT_NO_CONTENT");db.update("UPDATE export_batches SET state=?,revision=revision+1,bytes=?,sha256=?,generated_at=?,expires_at=?,lease_token=NULL,lease_until=NULL WHERE id=?",failed>0?"PARTIAL":"READY",bytes,sha,java.sql.Timestamp.from(stamp.generatedAt()),java.sql.Timestamp.from(stamp.expiresAt()),job.id());audit.record(job.actor(),job.tenant(),failed>0?"EXPORT_BATCH_PARTIAL":"EXPORT_BATCH_GENERATED",job.id(),"SUCCESS");
 }
 @Transactional public void fail(Job job,String code){if(db.queryForList("SELECT id FROM export_batches WHERE id=? AND lease_token=? AND state='GENERATING' FOR UPDATE",job.id(),job.token()).isEmpty())return;long bytes=db.queryForObject("SELECT coalesce(sum(octet_length(content)),0) FROM export_archive_chunks WHERE batch_id=?",Long.class,job.id());db.update("DELETE FROM export_archive_chunks WHERE batch_id=?",job.id());db.update("UPDATE export_batches SET state='FAILED',revision=revision+1,error_code=?,bytes=0,sha256=NULL,lease_token=NULL,lease_until=NULL,removed_bytes=removed_bytes+? WHERE id=?",code,bytes,job.id());}
 @Transactional public int expireDue(){return db.update("UPDATE export_batches SET state='EXPIRED',revision=revision+1,lease_token=NULL,lease_until=NULL,cleanup_state='PENDING',cleanup_reason='EXPIRED' WHERE cleanup_state='NONE' AND ((expires_at<=now()) OR (retention_deadline<=now()) OR (state IN('QUEUED','GENERATING','FAILED') AND created_at<now()-interval '1 day'))");}
 @Transactional public List<UUID> cleanupPending(){return db.queryForList("SELECT id FROM export_batches WHERE cleanup_state IN ('PENDING','FAILED') ORDER BY created_at,id LIMIT 10",UUID.class);}
 @Transactional public void cleanup(UUID id){var rows=db.queryForList("SELECT id FROM export_batches WHERE id=? AND cleanup_state IN ('PENDING','FAILED') FOR UPDATE",id);if(rows.isEmpty())return;long bytes=db.queryForObject("SELECT coalesce(sum(octet_length(content)),0) FROM export_archive_chunks WHERE batch_id=?",Long.class,id);db.update("DELETE FROM export_archive_chunks WHERE batch_id=?",id);db.update("UPDATE export_batch_items SET title=NULL,archive_path=NULL,sha256=NULL WHERE batch_id=?",id);db.update("UPDATE export_batches SET cleanup_state='COMPLETE',cleanup_attempts=cleanup_attempts+1,cleaned_at=now(),error_code=CASE WHEN error_code='EXPORT_CLEANUP_FAILED' THEN NULL ELSE error_code END,removed_bytes=removed_bytes+?,revision=revision+1 WHERE id=?",bytes,id);}
 @Transactional public void cleanupFailed(UUID id){db.update("UPDATE export_batches SET cleanup_state='FAILED',cleanup_attempts=cleanup_attempts+1,error_code='EXPORT_CLEANUP_FAILED',revision=revision+1 WHERE id=? AND cleanup_state IN ('PENDING','FAILED')",id);}
 private long chunks(UUID id,UUID generation,OutputStream out,MessageDigest digest)throws IOException{
  long[] bytes={0};int[] index={0};IOException[] failure={null};db.query(connection->{var st=connection.prepareStatement("SELECT ordinal,content FROM export_archive_chunks WHERE batch_id=? AND generation=? ORDER BY ordinal");st.setObject(1,id);st.setObject(2,generation);st.setFetchSize(1);return st;},rs->{while(rs.next()){if(rs.getInt(1)!=index[0]++)throw new IdentityException(503,"EXPORT_ARCHIVE_UNAVAILABLE");byte[] content=rs.getBytes(2);bytes[0]+=content.length;if(bytes[0]>MAX_ARCHIVE)throw new IdentityException(503,"EXPORT_ARCHIVE_UNAVAILABLE");if(digest!=null)digest.update(content);if(out!=null)try{out.write(content);}catch(IOException e){failure[0]=e;return null;}}return null;});if(failure[0]!=null)throw failure[0];return bytes[0];
 }
 /** Transaction keeps tenant/account grant locks until the bounded response finishes writing. */
 @Transactional public void download(UUID actor,UUID tenant,UUID id,Consumer<DownloadInfo> begin,OutputStream out)throws IOException{
  var r=row(actor,tenant,id,true);if(!usable(r))throw new IdentityException(410,"EXPORT_NOT_DOWNLOADABLE");UUID space=(UUID)r.get("workspace_id");String scope=(String)r.get("scope");sources.scope(actor,tenant,space,scope,true);int included=0;for(var i:rawItems(id))if("INCLUDED".equals(i.get("state"))){included++;sources.inspect(actor,tenant,space,scope,selection(i),true);sources.verifySources(actor,tenant,dependencies(id,(Integer)i.get("ordinal")));}if(included==0)throw new IdentityException(410,"EXPORT_NO_CONTENT");MessageDigest digest;try{digest=MessageDigest.getInstance("SHA-256");}catch(NoSuchAlgorithmException e){throw new IllegalStateException(e);}long bytes=chunks(id,(UUID)r.get("generation"),null,digest);String hash=HexFormat.of().formatHex(digest.digest());if(bytes!=(Long)r.get("bytes")||!hash.equals(r.get("sha256")))throw new IdentityException(503,"EXPORT_ARCHIVE_UNAVAILABLE");begin.accept(new DownloadInfo("dreamcore-export-"+id+".zip",bytes,hash));chunks(id,(UUID)r.get("generation"),out,null);audit.record(actor,tenant,"EXPORT_BATCH_DOWNLOAD",id,"SUCCESS");
 }
}
